import { renderHook, act } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import useSessionTimeout from '../hooks/useSessionTimeout'

jest.useFakeTimers()

const mockNavigate = jest.fn()
jest.mock('react-router-dom', () => ({
  MemoryRouter: ({ children }) => children,
  useNavigate: () => mockNavigate,
}))

const wrapper = ({ children }) => <MemoryRouter>{children}</MemoryRouter>

beforeEach(() => {
  jest.clearAllMocks()
  jest.clearAllTimers()
  localStorage.clear()
  localStorage.setItem('token', 'test-token')
  localStorage.setItem('user', JSON.stringify({ id: 1, email: 'test@test.lt' }))
})

describe('useSessionTimeout', () => {
  test('grąžina showWarning=false pradinėje būsenoje', () => {
    const { result } = renderHook(() => useSessionTimeout(), { wrapper })
    expect(result.current.showWarning).toBe(false)
  })

  test('po 9 minučių neaktyvumo parodo įspėjimą', () => {
    const { result } = renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(9 * 60 * 1000)
    })

    expect(result.current.showWarning).toBe(true)
  })

  test('po 10 minučių neaktyvumo pašalina vartotoją ir nukreipia į /login', () => {
    renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(10 * 60 * 1000)
    })
    act(() => {
      jest.advanceTimersByTime(500)
    })

    expect(localStorage.getItem('user')).toBeNull()
    expect(localStorage.getItem('token')).toBeNull()
    expect(mockNavigate).toHaveBeenCalledWith('/login?sessionExpired=true')
  })

  test('įspėjimo metu pelės judesys nepratęsia sesijos — po viso 10 min vis tiek atjungia', () => {
    renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(9 * 60 * 1000)
    })

    act(() => {
      window.dispatchEvent(new Event('mousemove'))
      jest.advanceTimersByTime(1 * 60 * 1000)
    })
    act(() => {
      jest.advanceTimersByTime(500)
    })

    expect(localStorage.getItem('user')).toBeNull()
    expect(mockNavigate).toHaveBeenCalledWith('/login?sessionExpired=true')
  })

  test('resetTimer atšaukia įspėjimą ir iš naujo paleidžia laikmatį', () => {
    const { result } = renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(9 * 60 * 1000)
    })
    expect(result.current.showWarning).toBe(true)

    act(() => {
      result.current.resetTimer(true)
    })
    expect(result.current.showWarning).toBe(false)

    act(() => {
      jest.advanceTimersByTime(8 * 60 * 1000)
    })
    expect(mockNavigate).not.toHaveBeenCalled()
  })

  test('vartotojo veikla (mousemove) atnaujina laikmatį', () => {
    renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(8 * 60 * 1000)
      window.dispatchEvent(new Event('mousemove'))
      jest.advanceTimersByTime(8 * 60 * 1000)
    })

    expect(mockNavigate).not.toHaveBeenCalled()
  })

  test('vartotojo veikla (keydown) atnaujina laikmatį', () => {
    renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(8 * 60 * 1000)
      window.dispatchEvent(new Event('keydown'))
      jest.advanceTimersByTime(8 * 60 * 1000)
    })

    expect(mockNavigate).not.toHaveBeenCalled()
  })

  test('vartotojo veikla (click) atnaujina laikmatį', () => {
    renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(8 * 60 * 1000)
      window.dispatchEvent(new Event('click'))
      jest.advanceTimersByTime(8 * 60 * 1000)
    })

    expect(mockNavigate).not.toHaveBeenCalled()
  })

  test('vartotojo veikla (scroll) atnaujina laikmatį', () => {
    renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(8 * 60 * 1000)
      window.dispatchEvent(new Event('scroll'))
      jest.advanceTimersByTime(8 * 60 * 1000)
    })

    expect(mockNavigate).not.toHaveBeenCalled()
  })

  test('vartotojo veikla (touchstart) atnaujina laikmatį', () => {
    renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      jest.advanceTimersByTime(8 * 60 * 1000)
      window.dispatchEvent(new Event('touchstart'))
      jest.advanceTimersByTime(8 * 60 * 1000)
    })

    expect(mockNavigate).not.toHaveBeenCalled()
  })

  test('logout išsiunčia beforeSessionTimeout įvykį', () => {
    const { result } = renderHook(() => useSessionTimeout(), { wrapper })
    const listener = jest.fn()
    window.addEventListener('beforeSessionTimeout', listener)

    act(() => {
      result.current.logout()
    })

    expect(listener).toHaveBeenCalledTimes(1)
    window.removeEventListener('beforeSessionTimeout', listener)
  })

  test('logout pašalina user ir token iš localStorage', () => {
    const { result } = renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      result.current.logout()
    })
    act(() => {
      jest.advanceTimersByTime(500)
    })

    expect(localStorage.getItem('user')).toBeNull()
    expect(localStorage.getItem('token')).toBeNull()
  })

  test('logout nukreipia į /login', () => {
    const { result } = renderHook(() => useSessionTimeout(), { wrapper })

    act(() => {
      result.current.logout()
    })
    act(() => {
      jest.advanceTimersByTime(500)
    })

    expect(mockNavigate).toHaveBeenCalledWith('/login?sessionExpired=true')
  })

  test('komponentui išmontuojant pašalinami event listeners ir laikmatiai', () => {
    const removeSpy = jest.spyOn(window, 'removeEventListener')
    const { unmount } = renderHook(() => useSessionTimeout(), { wrapper })

    unmount()

    expect(removeSpy).toHaveBeenCalledWith('mousemove', expect.any(Function))
    expect(removeSpy).toHaveBeenCalledWith('keydown', expect.any(Function))
    expect(removeSpy).toHaveBeenCalledWith('click', expect.any(Function))
    expect(removeSpy).toHaveBeenCalledWith('scroll', expect.any(Function))
    expect(removeSpy).toHaveBeenCalledWith('touchstart', expect.any(Function))

    removeSpy.mockRestore()
  })
})

import { useState, useEffect } from 'react'
import api from '../../services/api'

export default function SubjectsModal({ program, open, onClose }) {
  const [subjectsBySemester, setSubjectsBySemester] = useState({})
  const [activeTab, setActiveTab] = useState(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  useEffect(() => {
    if (!open || !program) return

    setLoading(true)
    setError(null)
    setSubjectsBySemester({})
    setActiveTab(null)
    setSearchQuery('')

    api.get(`/study-programs/${program.id}/subjects`)
      .then(({ data }) => {
        const grouped = {}
        data.forEach((subject) => {
          if (!grouped[subject.semester]) grouped[subject.semester] = []
          grouped[subject.semester].push(subject)
        })
        setSubjectsBySemester(grouped)
        const first = Object.keys(grouped).sort((a, b) => Number(a) - Number(b))[0]
        setActiveTab(first ?? null)
      })
      .catch(() => setError('Nepavyko užkrauti dalykų'))
      .finally(() => setLoading(false))
  }, [program?.id, open])

  useEffect(() => {
    if (!open) return
    const onKey = (e) => { if (e.key === 'Escape') onClose() }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [open, onClose])

  if (!open || !program) return null

  const semesters = Object.keys(subjectsBySemester).sort((a, b) => Number(a) - Number(b))

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      onClick={onClose}
    >
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" />

      <div
        className="relative bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 flex-shrink-0">
          <div>
            <h2 className="text-base font-semibold text-slate-900">{program.name}</h2>
            <p className="text-xs text-slate-400 mt-0.5">Studijų programos dalykai</p>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 rounded-lg flex items-center justify-center hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {!loading && !error && semesters.length > 0 && (
          <div className="flex flex-col gap-3 px-6 pt-4 pb-2 flex-shrink-0 border-b border-slate-100">
            <div className="flex gap-1 overflow-x-auto">
              {semesters.map((sem) => (
                <button
                  key={sem}
                  onClick={() => setActiveTab(sem)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-colors ${
                    activeTab === sem
                      ? 'bg-brand-600 text-white'
                      : 'text-slate-500 hover:bg-slate-100 hover:text-slate-700'
                  }`}
                >
                  {sem} semestras ({subjectsBySemester[sem].length})
                </button>
              ))}
            </div>
            <div className="relative">
              <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
              </svg>
              <input
                type="text"
                placeholder="Ieškoti dalyko pagal pavadinimą arba kodą..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-10 py-2 text-sm border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500 focus:border-transparent placeholder:text-slate-400"
              />
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              )}
            </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto px-6 py-4">
          {loading && (
            <div className="flex items-center justify-center gap-3 py-12 text-slate-400">
              <svg className="w-5 h-5 animate-spin" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0013.803-3.7M4.031 9.865a8.25 8.25 0 0113.803-3.7l3.181 3.182m0-4.991v4.99" />
              </svg>
              <span className="text-sm">Kraunama...</span>
            </div>
          )}

          {error && (
            <p className="text-sm text-red-500 text-center py-10">{error}</p>
          )}

          {!loading && !error && semesters.length === 0 && (
            <p className="text-sm text-slate-400 text-center py-10">Dalykų nerasta</p>
          )}

          {!loading && !error && activeTab && subjectsBySemester[activeTab] && (() => {
            const q = searchQuery.trim().toLowerCase()
            const filtered = q
              ? subjectsBySemester[activeTab].filter(
                  (s) =>
                    s.name.toLowerCase().includes(q) ||
                    (s.code && s.code.toLowerCase().includes(q))
                )
              : subjectsBySemester[activeTab]
            return (
            <ul className="space-y-2">
              {filtered.length === 0 ? (
                <p className="text-sm text-slate-400 py-6 text-center">
                  {q ? `Pagal „${searchQuery}" nieko nerasta` : 'Dalykų nerasta'}
                </p>
              ) : (
              filtered.map((subject) => (
                <li
                  key={subject.id}
                  className="flex items-center justify-between px-4 py-3 bg-slate-50 rounded-xl"
                >
                  <div>
                    <p className="text-sm font-medium text-slate-800">{subject.name}</p>
                    <p className="text-xs text-slate-400 mt-0.5">{subject.code}</p>
                  </div>
                  <span className="text-xs font-semibold text-brand-600 bg-brand-50 border border-brand-200 px-2.5 py-1 rounded-full flex-shrink-0 ml-4">
                    {subject.credits} kr.
                  </span>
                </li>
              ))
              )}
            </ul>
            )
          })()}
        </div>
      </div>
    </div>
  )
}

export default function ChatMessage({ message }) {
  const isUser = message.role === 'user'

  if (isUser) {
    const textContent = message.text || message.content
    return (
      <div className="flex justify-end">
        <div className="max-w-[75%] px-4 py-3 rounded-2xl rounded-br-md text-sm bg-brand-600 text-white shadow-sm">
          {message.image && (
            <img
              src={message.image}
              alt="Pridėta nuotrauka"
              className="max-w-full max-h-48 rounded-lg mb-2"
            />
          )}
          {textContent && <p className="whitespace-pre-wrap">{textContent}</p>}
        </div>
      </div>
    )
  }

  // DI atsakymas — struktūrizuotas arba paprastas
  const { text, content, recommendations, arguments: args, disclaimer } = message
  const assistantText = text || content

  return (
    <div className="flex justify-start">
      <div className="max-w-[80%] rounded-2xl rounded-bl-md text-sm bg-white border border-slate-200 text-slate-700 overflow-hidden shadow-sm">

        {/* Paprastas tekstas arba įžanga */}
        {assistantText && (
          <div className="px-4 py-3">
            <p className="whitespace-pre-wrap">{assistantText}</p>
          </div>
        )}

        {/* Rekomendacijos */}
        {recommendations && recommendations.length > 0 && (
          <div className="border-t border-slate-100 px-4 py-3">
            <p className="text-xs font-semibold text-brand-600 uppercase tracking-wide mb-2">
              Rekomenduojami dalykrai
            </p>
            <div className="space-y-2">
              {recommendations.map((rec, i) => (
                <div key={i} className="flex gap-2">
                  <span className="flex-shrink-0 w-5 h-5 rounded-full bg-brand-50 text-brand-700 text-xs flex items-center justify-center font-semibold">
                    {i + 1}
                  </span>
                  <div>
                    <p className="font-medium text-slate-800">{rec.name}</p>
                    {rec.reason && (
                      <p className="text-xs text-slate-500 mt-0.5">{rec.reason}</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Argumentai */}
        {args && args.length > 0 && (
          <div className="border-t border-slate-100 px-4 py-3 bg-slate-50">
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">
              Argumentai
            </p>
            <ul className="space-y-1">
              {args.map((arg, i) => (
                <li key={i} className="flex gap-2 text-xs text-slate-600">
                  <span className="text-brand-400 flex-shrink-0">•</span>
                  {arg}
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Atsakomybės apribojimas */}
        {disclaimer && (
          <div className="border-t border-slate-100 px-4 py-2">
            <p className="text-xs text-slate-400 italic">{disclaimer}</p>
          </div>
        )}
      </div>
    </div>
  )
}

import { useState, useRef, useEffect } from 'react'
import { useParams } from 'react-router-dom'
import ChatMessage from './ChatMessage'
import ChatInput from './ChatInput'
import useProfile from '../../hooks/useProfile'
import api from '../../services/api'

const SESSION_KEY = 'chat_new_messages'

export default function ChatWindow() {
  const { id } = useParams()
  const [messages, setMessages] = useState(() => {
    if (!id) {
      try {
        const saved = sessionStorage.getItem(SESSION_KEY)
        return saved ? JSON.parse(saved) : []
      } catch { return [] }
    }
    return []
  })
  const [loading, setLoading] = useState(false)
  const [profileOpen, setProfileOpen] = useState(false)
  const [title, setTitle] = useState('')
  const [isEditingTitle, setIsEditingTitle] = useState(false)
  const bottomRef = useRef(null)
  const { profile, isEmpty, hasValidHobbies, buildSystemPrompt } = useProfile()

  // Persist new-conversation messages to sessionStorage
  useEffect(() => {
    if (!id) {
      if (messages.length > 0) {
        sessionStorage.setItem(SESSION_KEY, JSON.stringify(messages))
      } else {
        sessionStorage.removeItem(SESSION_KEY)
      }
    }
  }, [messages, id])

  // Load chat history from API
  useEffect(() => {
    if (id) {
      setLoading(true)
      // Fetch messages
      api.get(`/conversations/${id}`)
        .then(res => setMessages(res.data))
        .catch(err => console.error('Failed to load messages', err))
        .finally(() => setLoading(false))

      // Fetch conversation list to get the title (simplified for now)
      api.get('/conversations')
        .then(res => {
          const conv = res.data.find(c => String(c.id) === id)
          if (conv) setTitle(conv.title)
        })
    } else {
      setTitle('')
    }
  }, [id])

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const handleRename = async () => {
    if (!id || !title.trim()) return

    // SCRUM-79: Truncate title before sending
    const finalTitle = title.trim().substring(0, 100)

    try {
      await api.patch(`/conversations/${id}/rename`, { title: finalTitle })
      setIsEditingTitle(false)
      // Dispatch custom event to notify Sidebar
      window.dispatchEvent(new CustomEvent('conversation-renamed', { detail: { id, title: finalTitle } }))
    } catch (err) {
      console.error('Failed to rename', err)
    }
  }

  const handleSend = async (msg) => {
    const userMessage = { id: Date.now(), role: 'user', ...msg }
    setMessages((prev) => [...prev, userMessage])
    setLoading(true)

    try {
      const systemPrompt = buildSystemPrompt()
      const allMessages = [...messages, userMessage].map(m => ({
        role: m.role,
        content: m.text || m.content || '',
      })).filter(m => m.content)

      const res = await api.post('/chat', { systemPrompt, messages: allMessages })

      setMessages((prev) => [
        ...prev,
        { id: Date.now() + 1, role: 'assistant', text: res.data.text },
      ])
    } catch {
      setMessages((prev) => [
        ...prev,
        { id: Date.now() + 1, role: 'assistant', text: 'Atsiprašome, įvyko klaida. Bandykite dar kartą.' },
      ])
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex flex-col h-[calc(100vh-10rem)] bg-white border border-slate-200 rounded-2xl overflow-hidden">

      {/* Title Bar */}
      <div className="px-4 py-3 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
        {isEditingTitle ? (
          <div className="flex items-center gap-2 flex-1 max-w-md">
            <input
              autoFocus
              type="text"
              value={title}
              maxLength={100}
              onChange={(e) => setTitle(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleRename()}
              onBlur={handleRename}
              className="flex-1 px-3 py-1 text-sm font-medium border border-brand-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500 bg-white"
            />
            <span className="text-[10px] text-slate-400 font-mono">{title.length}/100</span>
          </div>
        ) : (
          <div className="flex items-center gap-2 group cursor-pointer" onClick={() => id && setIsEditingTitle(true)}>
            <h2 className="text-sm font-bold text-slate-700 truncate max-w-[300px]">
              {id ? (title || 'Bevardis pokalbis') : 'Nauja rekomendacija'}
            </h2>
            {id && (
              <svg className="w-3.5 h-3.5 text-slate-300 group-hover:text-brand-500 transition-colors" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L6.832 19.82a4.5 4.5 0 01-1.897 1.13l-2.685.8.8-2.685a4.5 4.5 0 011.13-1.897L16.863 4.487zm0 0L19.5 7.125" />
              </svg>
            )}
          </div>
        )}

        <div className="flex items-center gap-4">
          <button
            onClick={() => setProfileOpen((v) => !v)}
            className="flex items-center gap-2 text-xs text-slate-500 hover:text-slate-700 transition-colors"
          >
            <span
              className={`w-2 h-2 rounded-full flex-shrink-0 ${isEmpty ? 'bg-amber-400' : 'bg-green-400'}`}
            />
            <span className="hidden sm:inline">{isEmpty ? 'Profilis neužpildytas' : 'Profilis aktyvus'}</span>
            <svg
              className={`w-3 h-3 transition-transform ${profileOpen ? 'rotate-180' : ''}`}
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
            </svg>
          </button>
        </div>
      </div>

      {/* Profilio detalių išskleidimas */}
      {profileOpen && (
        <div className="bg-slate-50 border-b border-slate-100 p-4 text-xs text-slate-500 space-y-0.5 animate-in slide-in-from-top-1">
          {profile.university && <p><span className="text-slate-400">Universitetas:</span> {profile.university}</p>}
          {profile.studyProgram && <p><span className="text-slate-400">Studijų programa:</span> {profile.studyProgram}</p>}
          {hasValidHobbies && <p><span className="text-slate-400">Hobiai:</span> {profile.hobbies.map(h => h.name).join(', ')}</p>}
          {!hasValidHobbies && (
            <p className="text-amber-500">
              Hobių informacija nepakankama — pridėkite bent 1 hobį <a href="/profilis" className="underline font-bold">profilyje</a> geresnėms rekomendacijoms.
            </p>
          )}
          {isEmpty && (
            <p className="text-amber-500">
              Eikite į <a href="/profilis" className="underline font-bold">Mano profilį</a> ir užpildykite informaciją.
            </p>
          )}
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-center">
            <div className="w-12 h-12 rounded-full bg-brand-50 flex items-center justify-center mb-3">
              <svg className="w-6 h-6 text-brand-600" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
