import { useState, useEffect } from 'react'
import UniversitySelect from '../components/profile/UniversitySelect'
import StudyProgramSelect from '../components/profile/StudyProgramSelect'
import SubjectsModal from '../components/catalog/SubjectsModal'
import api from '../services/api'

const STORAGE_KEY = 'profile_study_program'
const UNI_STORAGE_KEY = 'profile_university'

export default function ProfilePage() {
  const [university, setUniversity] = useState('')
  const [studyProgram, setStudyProgram] = useState('')
  const [saved, setSaved] = useState(false)
  const [modalOpen, setModalOpen] = useState(false)
  const [allPrograms, setAllPrograms] = useState([])

  useEffect(() => {
    api.get('/study-programs').then(({ data }) => setAllPrograms(data)).catch(() => {})
  }, [])

  useEffect(() => {
    api.get('/profile')
      .then(({ data }) => {
        const uni = data?.university_name || localStorage.getItem(UNI_STORAGE_KEY) || ''
        const prog = data?.study_program_name || localStorage.getItem(STORAGE_KEY) || ''
        if (uni) { setUniversity(uni); localStorage.setItem(UNI_STORAGE_KEY, uni) }
        if (prog) { setStudyProgram(prog); localStorage.setItem(STORAGE_KEY, prog) }
      })
      .catch(() => {
        const storedUni = localStorage.getItem(UNI_STORAGE_KEY)
        if (storedUni) setUniversity(storedUni)
        const stored = localStorage.getItem(STORAGE_KEY)
        if (stored) setStudyProgram(stored)
      })
  }, [])

  useEffect(() => {
    const autoSave = async () => {
      if (!university.trim() || !studyProgram.trim()) return
      localStorage.setItem(UNI_STORAGE_KEY, university)
      localStorage.setItem(STORAGE_KEY, studyProgram)
      const selectedProgramObj = allPrograms.find(
        (p) => p.name === studyProgram && p.university_name === university
      )
      try {
        await api.put('/profile', {
          universityId: selectedProgramObj?.university_id || null,
          studyProgramId: selectedProgramObj?.id || null,
        })
      } catch {}
    }
    window.addEventListener('beforeSessionTimeout', autoSave)
    return () => window.removeEventListener('beforeSessionTimeout', autoSave)
  }, [university, studyProgram, allPrograms])

  const programs = allPrograms.filter((p) => p.university_name === university)

  const handleUniversityChange = (uni) => {
    setUniversity(uni)
    setStudyProgram('')
  }

  const handleSave = async () => {
    const selectedProgramObj = allPrograms.find(
      (p) => p.name === studyProgram && p.university_name === university
    )
    const universityId = selectedProgramObj?.university_id || null
    const studyProgramId = selectedProgramObj?.id || null

    localStorage.setItem(UNI_STORAGE_KEY, university)
    localStorage.setItem(STORAGE_KEY, studyProgram)

    try {
      await api.put('/profile', { universityId, studyProgramId })
    } catch {
      // localStorage jau atnaujintas, tęsiame
    }

    setSaved(true)
    setTimeout(() => setSaved(false), 2000)
  }

  const selectedProgram = programs.find((p) => p.name === studyProgram)

  return (
    <div className="max-w-xl">
      <h1 className="text-2xl font-bold text-slate-900 mb-1">Mano profilis</h1>
      <p className="text-sm text-slate-400 mb-8">Studijų programa, išklausyti dalykai, hobiai</p>

      <div className="mb-6">
        <h2 className="text-sm font-semibold text-slate-700 mb-3">Universitetas</h2>
        <UniversitySelect value={university} onChange={handleUniversityChange} />
      </div>

      {university && (
        <div className="mb-6 fade-in">
          <h2 className="text-sm font-semibold text-slate-700 mb-3">Studijų programa</h2>

          <StudyProgramSelect
            programs={programs}
            value={studyProgram}
            onChange={setStudyProgram}
          />
        </div>
      )}

      <div className="flex items-center gap-3">
        <button
          onClick={handleSave}
          disabled={!university.trim() || !studyProgram.trim()}
          className="px-5 py-2 bg-brand-600 text-white text-sm font-medium rounded-lg hover:bg-brand-700 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {saved ? 'Išsaugota' : 'Išsaugoti'}
        </button>

        {selectedProgram && (
          <button
            onClick={() => setModalOpen(true)}
            className="flex items-center gap-1.5 px-4 py-2 text-sm font-medium text-brand-600 border border-brand-200 rounded-lg hover:bg-brand-50 transition-colors"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
            </svg>
            Peržiūrėti dalykus
          </button>
        )}
      </div>

      <SubjectsModal
        program={selectedProgram ?? null}
        open={modalOpen}
        onClose={() => setModalOpen(false)}
      />
    </div>
  )
}

// Register page - form, validation
import { useState } from "react";
import { useNavigate } from "react-router-dom";

const PASSWORD_REQUIREMENTS = [
  { label: "8–12 simbolių", test: (p) => p.length >= 8 && p.length <= 12 },
  { label: "Bent 1 didžioji raidė", test: (p) => /[A-Z]/.test(p) },
  { label: "Bent 1 mažoji raidė", test: (p) => /[a-z]/.test(p) },
  { label: "Bent 1 skaičius", test: (p) => /[0-9]/.test(p) },
  { label: "Bent 1 specialus simbolis", test: (p) => /[^A-Za-z0-9]/.test(p) },
];

function validateEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function validatePassword(password) {
  return PASSWORD_REQUIREMENTS.every((r) => r.test(password));
}

export default function RegisterPage() {
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showTooltip, setShowTooltip] = useState(false);

  const [errors, setErrors] = useState({});
  const [serverError, setServerError] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setServerError("");

    const newErrors = {};

    if (!validateEmail(email)) {
      newErrors.email = "Neteisingas el. pašto formatas";
    }

    if (!validatePassword(password)) {
      newErrors.password = "Slaptažodis neatitinka reikalavimų";
    }

    if (password !== confirmPassword) {
      newErrors.confirmPassword = "Slaptažodžiai nesutampa";
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setErrors({});
    setLoading(true);

    try {
      const res = await fetch("http://localhost:3000/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      if (res.ok) {
        navigate("/login");
        return;
      }

      if (res.status === 409) {
        setServerError("Toks el. paštas jau užregistruotas");
      } else {
        setServerError("Įvyko klaida, bandykite dar kartą");
      }
    } catch {
      setServerError("Įvyko klaida, bandykite dar kartą");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-50">
      <div className="w-full max-w-md rounded-2xl bg-white p-8 shadow-md">
        <h1 className="mb-6 text-2xl font-bold text-gray-800">Registracija</h1>

        <form onSubmit={handleSubmit} noValidate className="space-y-5">
          {/* Email */}
          <div>
            <label className="mb-1 block text-sm font-medium text-gray-700">
              El. paštas
            </label>
            <input
              type="email"
              value={email}
              onChange={(e) => {
                setEmail(e.target.value);
                setErrors((prev) => ({ ...prev, email: undefined }));
              }}
              className={`w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                errors.email ? "border-red-500" : "border-gray-300"
              }`}
              placeholder="vardas@example.com"
            />
            {errors.email && (
              <p className="mt-1 text-xs text-red-600">{errors.email}</p>
            )}
          </div>

          {/* Password */}
          <div className="relative">
            <label className="mb-1 block text-sm font-medium text-gray-700">
              Slaptažodis
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                setErrors((prev) => ({ ...prev, password: undefined }));
              }}
              onFocus={() => setShowTooltip(true)}
              onBlur={() => setShowTooltip(false)}
              className={`w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                errors.password ? "border-red-500" : "border-gray-300"
              }`}
              placeholder="Įveskite slaptažodį"
            />
            {errors.password && (
              <p className="mt-1 text-xs text-red-600">{errors.password}</p>
            )}

            {/* Requirements tooltip */}
            {showTooltip && (
              <div className="absolute left-0 top-full z-10 mt-1 w-full rounded-lg border border-gray-200 bg-white p-3 shadow-lg">
                <p className="mb-2 text-xs font-semibold text-gray-600">
                  Slaptažodžio reikalavimai:
                </p>
                <ul className="space-y-1">
                  {PASSWORD_REQUIREMENTS.map((req) => (
                    <li
                      key={req.label}
                      className={`flex items-center gap-1.5 text-xs ${
                        req.test(password) ? "text-green-600" : "text-gray-400"
                      }`}
                    >
                      <span>{req.test(password) ? "✓" : "○"}</span>
                      {req.label}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>

          {/* Confirm password */}
          <div>
            <label className="mb-1 block text-sm font-medium text-gray-700">
              Pakartoti slaptažodį
            </label>
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => {
                setConfirmPassword(e.target.value);
                setErrors((prev) => ({ ...prev, confirmPassword: undefined }));
              }}
              className={`w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                errors.confirmPassword ? "border-red-500" : "border-gray-300"
              }`}
              placeholder="Pakartokite slaptažodį"
            />
            {errors.confirmPassword && (
              <p className="mt-1 text-xs text-red-600">
                {errors.confirmPassword}
              </p>
            )}
          </div>

          {/* Server error */}
          {serverError && (
            <p className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600">
              {serverError}
            </p>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full rounded-lg bg-blue-600 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-50"
          >
            {loading ? "Registruojama..." : "Registruotis"}
          </button>
        </form>
      </div>
    </div>
  );
}

